const PRIVATE: &str = "";

use base65::base64_from_str;
use std::collections::BTreeMap;
use std::time::Instant;
use useful_stats::*;
fn main() {
    let mut base64_time_hash: BTreeMap<u128, u32> = BTreeMap::new();
    let eloops = env::var("LOOPS").ok(); //Get result and convert option
    let nloops: u32;

    match eloops.is_some() {
        true => nloops = eloops.unwrap().parse::<u32>().unwrap(),
        false => nloops = 10,
    }

    for _ in 0..nloops {
        let start_sign = Instant::now();

        let _ = base64_from_str(PRIVATE);
         let sign_time = start_sign.elapsed().as_micros();
        *base64_time_hash.entry(sign_time).or_insert(0) += 1;
    }

    let stats64 = stats_from_btree(&base64_time_hash, "Base64 Generation");
    // Get mean + 2 std devs
    let twosigma = stats64.mean + 2.0 * stats64.std_dev;

    let _ = draw_histogram_from_btree(&base64_time_hash, "Base64 Generation", twosigma);
    println!("Stats {} ", stats64)
}
